/// `Recipe.SetIngredients(params int[])` (Recipe.cs:16768)
pub unsafe fn set_ingredients(this: *mut terraria::recipe::Recipe, mut ingredients: Arr<i32>) {
    if (ingredients.len() == 1)
    {
        ingredients = Arr::<i32>::from_slice(&[(*ingredients.at(0)), 1i32]);
    }
    if (!(rt::rem(ingredients.len(), 2) == 0))
    {
        rt::throw(rt::exc("System.Exception", s!("Bad ingredients amount")));
    }
    {
        let mut i: i32 = 0;
        'l1: loop
        {
            rt::yield_point();
            if !((i < ingredients.len())) { break 'l1; }
            'c1:
            {
                let mut num: i32 = rt::div(i, 2);
                terraria::item::set_defaults((*(*this).required_item.at(num)).ptr(), (*ingredients.at(i)), Gc::<terraria::game_content::items::item_variant::ItemVariant>::NULL);
                (*(*(*this).required_item.at(num)).ptr()).stack = (*ingredients.at(i.wrapping_add(1)));
            }
            i = i.wrapping_add(2i32);
        }
    }
}

