/// `Recipe.AddRecipe()` (Recipe.cs:16795)
pub unsafe fn add_recipe() {
    if ((*(*terraria::recipe::s()).current_recipe.ptr()).required_tile == 13)
    {
        (*(*terraria::recipe::s()).current_recipe.ptr()).alchemy = true;
    }
    (*(*terraria::main::s()).recipe.at((*terraria::recipe::s()).num_recipes)) = rt::wbv((*terraria::recipe::s()).current_recipe);
    if ((*(*terraria::recipe::s()).current_recipe.ptr()).required_tile >= 0)
    {
        (*(*terraria::recipe::s()).tile_used_in_recipes.at((*(*terraria::recipe::s()).current_recipe.ptr()).required_tile)) = true;
    }
    (*terraria::recipe::s()).current_recipe = rt::wbv(terraria::recipe::new());
    (*terraria::recipe::s()).num_recipes = (*terraria::recipe::s()).num_recipes.wrapping_add(1);
}

/// `Recipe.GetRequiredTileStyle(int)` (Recipe.cs:16810)
pub unsafe fn get_required_tile_style(mut tileID: i32) -> i32 {
    if (tileID == 26)
    {
        if (!(*terraria::world_gen::s()).crimson)
        {
            return 0;
        }
        return 1;
    }
    return 0;
    rt::unreachable()
}

/// `Recipe.GetRequiredTileName(int)` (Recipe.cs:16823)
pub unsafe fn get_required_tile_name(mut tileId: i32) -> Str {
    let mut requiredTileStyle: i32 = terraria::recipe::get_required_tile_style(tileId);
    return terraria::lang::get_map_object_name(terraria::map::map_helper::tile_to_lookup(tileId, requiredTileStyle));
    rt::unreachable()
}

